
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE UNIQUE,phone TEXT UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','worker','admin')),is_suspended INTEGER NOT NULL DEFAULT 0,language TEXT DEFAULT 'en',locality TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS services(id TEXT PRIMARY KEY,name TEXT NOT NULL,name_bn TEXT,name_hi TEXT,description TEXT,icon TEXT,active INTEGER NOT NULL DEFAULT 1,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT);
CREATE TABLE IF NOT EXISTS service_tasks(id TEXT PRIMARY KEY,service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE,name TEXT NOT NULL,name_bn TEXT,name_hi TEXT,description TEXT,base_price REAL NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT);
CREATE TABLE IF NOT EXISTS locations(id TEXT PRIMARY KEY,name TEXT NOT NULL,district TEXT DEFAULT 'Nadia',state TEXT DEFAULT 'West Bengal',latitude REAL,longitude REAL,active INTEGER DEFAULT 1,metadata TEXT DEFAULT '{}');
CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,legacy_id TEXT UNIQUE,trade_id TEXT NOT NULL REFERENCES services(id),bio TEXT,profile_photo_url TEXT,locality TEXT,address_area TEXT,latitude REAL,longitude REAL,is_available INTEGER NOT NULL DEFAULT 0,kyc_status TEXT NOT NULL DEFAULT 'pending',identity_verified INTEGER NOT NULL DEFAULT 0,background_verified INTEGER NOT NULL DEFAULT 0,aadhaar_verified INTEGER NOT NULL DEFAULT 0,experience_years INTEGER NOT NULL DEFAULT 0,jobs_completed INTEGER NOT NULL DEFAULT 0,rating_average REAL NOT NULL DEFAULT 0,rating_count INTEGER NOT NULL DEFAULT 0,half_day_rate REAL NOT NULL DEFAULT 0,daily_rate REAL NOT NULL DEFAULT 0,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT,updated_at TEXT,last_active_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS workers_user_id_unique ON workers(user_id);
CREATE TABLE IF NOT EXISTS worker_skills(id TEXT PRIMARY KEY,worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE,skill_name TEXT NOT NULL,created_at TEXT,UNIQUE(worker_id,skill_name));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,customer_id TEXT REFERENCES users(id),service_id TEXT NOT NULL REFERENCES services(id),task_id TEXT REFERENCES service_tasks(id),title TEXT NOT NULL,description TEXT,photo_url TEXT,locality TEXT NOT NULL,address_details TEXT,latitude REAL,longitude REAL,urgency TEXT NOT NULL DEFAULT 'normal',preferred_date TEXT,preferred_time TEXT,estimated_price_min REAL,estimated_price_max REAL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,legacy_id TEXT UNIQUE,job_id TEXT REFERENCES jobs(id),customer_id TEXT REFERENCES users(id),worker_id TEXT REFERENCES workers(id),service_id TEXT NOT NULL REFERENCES services(id),task_id TEXT REFERENCES service_tasks(id),booking_type TEXT NOT NULL DEFAULT 'immediate',scheduled_date TEXT,scheduled_slot TEXT,locality TEXT,address_details TEXT,estimated_price_min REAL,estimated_price_max REAL,final_price REAL,payment_method TEXT,payment_status TEXT DEFAULT 'pending',status TEXT NOT NULL DEFAULT 'pending',otp TEXT,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT,updated_at TEXT,completed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS bookings_job_id_unique ON bookings(job_id) WHERE job_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS job_offers(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE,offered_price REAL NOT NULL,message TEXT,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT,updated_at TEXT,UNIQUE(job_id,worker_id));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE CASCADE,customer_id TEXT REFERENCES users(id),worker_id TEXT NOT NULL REFERENCES workers(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),review_text TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE,job_id TEXT REFERENCES jobs(id) ON DELETE SET NULL,booking_id TEXT REFERENCES bookings(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'active',last_message_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_participants(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,last_read_at TEXT,joined_at TEXT NOT NULL,UNIQUE(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS quotations(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,booking_id TEXT REFERENCES bookings(id) ON DELETE SET NULL,sender_id TEXT NOT NULL REFERENCES users(id),labour_cost REAL NOT NULL,material_cost REAL NOT NULL DEFAULT 0,travel_cost REAL NOT NULL DEFAULT 0,total_estimate REAL NOT NULL DEFAULT 0,notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'proposed',response_note TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,message_type TEXT NOT NULL,message_text TEXT,attachment_url TEXT,quotation_id TEXT REFERENCES quotations(id) ON DELETE SET NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_reports(id TEXT PRIMARY KEY,message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,reporter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,UNIQUE(message_id,reporter_id));
CREATE TABLE IF NOT EXISTS contact_sharing_attempts(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,detection_type TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_action_logs(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),target_user_id TEXT REFERENCES users(id),conversation_id TEXT REFERENCES conversations(id),report_id TEXT REFERENCES message_reports(id),action TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_rate_limits(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,window_started_at TEXT NOT NULL,message_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_rate_limits(key TEXT PRIMARY KEY,window_started_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(sid TEXT PRIMARY KEY,sess TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_workers_trade ON workers(trade_id,is_available);
CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON jobs(status,created_at);
CREATE INDEX IF NOT EXISTS idx_bookings_customer ON bookings(customer_id,created_at);
CREATE INDEX IF NOT EXISTS idx_bookings_worker ON bookings(worker_id,created_at);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS idx_participants_user ON conversation_participants(user_id,conversation_id);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
